static char *fgets_strip(char *buf, int size, FILE *f_in)
{
        // strip trailing spaces, and truncate lines at // comment
        int len;
        char *p;

        if (fgets(buf, size, f_in) == NULL)
                return NULL;

        if (buf[0] == '#') {
                buf[0] = 0;
                return buf;
        }

        len = strlen(buf);
        while ((--len > 0) && isspace(buf[len]))
                buf[len] = 0;

        if ((p = strstr(buf, "//")) != NULL)
                *p = 0;

        return buf;
}

