float polint(float xa[], float ya[], int n, float x)
{
        // General polinomial interpolation routine, xa[1...n] ya[1...n]
        int i, m, ns = 1;
        float den, dif, dift, ho, hp, w;
        float y; // result
        float c[9], d[9];

        dif = fabs(x-xa[1]);

        for (i = 1; i <= n; i++) {
                if ((dift = fabs(x-xa[i])) < dif) {
                        ns = i;
                        dif = dift;
                }
                c[i] = ya[i];
                d[i] = ya[i];
        }
        y = ya[ns--];
        for (m = 1; m < n; m++) {
                for (i = 1; i <= n-m; i++) {
                        ho = xa[i]-x;
                        hp = xa[i+m]-x;
                        w = c[i+1]-d[i];
                        if ((den = ho-hp) == 0.0)
                                return ya[2]; // two input xa are identical
                        den = w/den;
                        d[i] = hp*den;
                        c[i] = ho*den;
                }
                y += ((2*ns < (n-m) ? c[ns+1] : d[ns--]));
        }
        return y;
}

