                0
        };

        if (iswalpha(c))
                return 1;

        if (c < 0x300)
                return 0;

        if ((c >= 0x901) && (c <= 0xdf7)) {
                // Indic scripts: Devanagari, Tamil, etc
                if ((c & 0x7f) < 0x64)
                        return 1;
                if (lookupwchar(extra_indic_alphas, c) != 0)
                        return 1;
                if ((c >= 0xd7a) && (c <= 0xd7f))
                        return 1; // malaytalam chillu characters

                return 0;
        }

        if ((c >= 0x5b0) && (c <= 0x5c2))
                return 1; // Hebrew vowel marks

        if (c == 0x0605)
                return 1;

        if ((c == 0x670) || ((c >= 0x64b) && (c <= 0x65e)))
                return 1; // arabic vowel marks

