ALPHABET *AlphabetFromChar(int c)
{
        // Find the alphabet from a character.
        ALPHABET *alphabet = alphabets;

        while (alphabet->name != NULL) {
                if (c <= alphabet->range_max) {
                        if (c >= alphabet->range_min)
                                return alphabet;
                        else
                                break;
                }
                alphabet++;
        }
        return NULL;
}

