    89  static int attrcmp(const wchar_t *string1, const char *string2)
    90  {
    91          int ix;
    92
    93          if (string1 == NULL)
    94                  return 1;
    95
    96          for (ix = 0; (string1[ix] == string2[ix]) && (string1[ix] != 0); ix++)
    97                  ;
    98          if (((string1[ix] == '"') || (string1[ix] == '\'')) && (string2[ix] == 0))
    99                  return 0;
   100          return 1;
   101  }
