   131  static int attrcopy_utf8(char *buf, const wchar_t *pw, int len)
   132  {
   133          // Convert attribute string into utf8, write to buf, and return its utf8 length
   134          unsigned int c;
   135          int ix = 0;
   136          int n;
   137          int prev_c = 0;
   138
   139          if (pw != NULL) {
   140                  while ((ix < (len-4)) && ((c = *pw++) != 0)) {
   141                          if ((c == '"') && (prev_c != '\\'))
   142                                  break; // " indicates end of attribute, unless preceded by backstroke
   143                          n = utf8_out(c, &buf[ix]);
   144                          ix += n;
   145                          prev_c = c;
   146                  }
   147          }
   148          buf[ix] = 0;
   149          return ix;
   150  }
